const listAccessibleProperties = `-- name: ListAccessibleProperties :many
SELECT p.id, p.owner_account_id, p.status, p.category, p.property_type, p.title, p.description, p.timezone, p.bedrooms, p.bathrooms, p.floor_area_sqm, p.year_built, p.transaction_ready, p.restriction_reason, p.external_ref, p.import_id, p.version, p.created_at, p.updated_at FROM properties p
 WHERE p.id IN (SELECT pa.property_id FROM property_access pa
                 WHERE pa.account_id = $1
                   AND (pa.valid_from IS NULL OR pa.valid_from <= $2::timestamptz)
                   AND (pa.valid_until IS NULL OR pa.valid_until > $2::timestamptz))
   AND ($3::text IS NULL OR p.status = $3::text)
   AND ($4::text IS NULL OR p.category = $4::text)
   AND ($5::timestamptz IS NULL OR (p.created_at, p.id) < ($5::timestamptz, $6::uuid))
 ORDER BY p.created_at DESC, p.id DESC
 LIMIT $7
`

type ListAccessiblePropertiesParams struct {
	AccountID ids.ID
	Now       time.Time
	Status    *string
	Category  *string
	CursorAt  *time.Time
	CursorID  *ids.ID
	MaxRows   int32
}

func (q *Queries) ListAccessibleProperties(ctx context.Context, db DBTX, arg ListAccessiblePropertiesParams) ([]Property, error) {
	rows, err := db.Query(ctx, listAccessibleProperties,
		arg.AccountID,
		arg.Now,
		arg.Status,
		arg.Category,
		arg.CursorAt,
		arg.CursorID,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Property
	for rows.Next() {
		var i Property
		if err := rows.Scan(
			&i.ID,
			&i.OwnerAccountID,
			&i.Status,
			&i.Category,
			&i.PropertyType,
			&i.Title,
			&i.Description,
			&i.Timezone,
			&i.Bedrooms,
			&i.Bathrooms,
			&i.FloorAreaSqm,
			&i.YearBuilt,
			&i.TransactionReady,
			&i.RestrictionReason,
			&i.ExternalRef,
			&i.ImportID,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

